import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

type Tab = 'dashboard' | 'courses' | 'timetable' | 'results' | 'exams' | 'fees' | 'documents' | 'resources' | 'support' | 'profile' | 'password';

const StudentDashboard: React.FC = () => {
  const [activeTab, setActiveTab] = useState<Tab>('dashboard');
  const [profile, setProfile] = useState<any>(null);
  const [fees, setFees] = useState<any>(null);
  const [announcements, setAnnouncements] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  // Shared state
  const [editPhone, setEditPhone] = useState('');
  const [editAddress, setEditAddress] = useState('');

  const getToken = () => localStorage.getItem('studentToken');
  const logout = () => { localStorage.removeItem('studentToken'); localStorage.removeItem('studentInfo'); navigate('/student/login'); };

  const authFetch = useCallback(async (url: string, options: RequestInit = {}) => {
    const token = getToken();
    if (!token) { navigate('/student/login'); return null; }
    const res = await fetch(url, { ...options, headers: { ...options.headers, 'Content-Type': 'application/json', Authorization: `Bearer ${token}` } });
    if (res.status === 401 || res.status === 403) { logout(); return null; }
    return res.json();
  }, [navigate]);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      const [p, f, a] = await Promise.all([
        authFetch(`${API}/api/students/profile`),
        authFetch(`${API}/api/students/fees`),
        authFetch(`${API}/api/students/announcements`),
      ]);
      if (p?.success) { setProfile(p.profile); setEditPhone(p.profile.phone); setEditAddress(p.profile.postalAddress); }
      if (f?.success) setFees(f.fees);
      if (a?.success) setAnnouncements(a.announcements || []);
      setLoading(false);
    };
    load();
  }, [authFetch]);

  const fmt = (n: number) => `GHS ${n.toLocaleString('en-GH', { minimumFractionDigits: 2 })}`;

  if (loading) return <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '100vh' }}><p>Loading portal...</p></div>;

  return (
    <div>
      <header className="header">
        <div className="header-content">
          <div className="logo-section">
            <img src="http://wuc.edu.gh/wp-content/uploads/2025/05/WC-logo-on-white-1.jpg" alt="WUC Logo" />
            <div><h1>Withrow University College</h1><span className="logo-sub">Student Portal</span></div>
          </div>
          <nav><ul className="nav-links">
            <li><span style={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.8rem' }}>{profile?.firstName} {profile?.lastName}</span></li>
            <li><button onClick={logout} className="btn btn-ghost btn-sm" style={{ color: 'white', borderColor: 'rgba(255,255,255,0.3)' }}>Logout</button></li>
          </ul></nav>
        </div>
      </header>

      <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '1.5rem' }}>
        {/* Navigation Tabs */}
        <div style={{ display: 'flex', gap: '0.15rem', marginBottom: '1.5rem', overflowX: 'auto', borderBottom: '2px solid var(--border)', paddingBottom: 0 }}>
          {([
            { key: 'dashboard', label: '🏠 Home' },
            { key: 'courses', label: '📚 Courses' },
            { key: 'timetable', label: '📅 Timetable' },
            { key: 'results', label: '📊 Results' },
            { key: 'exams', label: '📝 Exams' },
            { key: 'fees', label: '💰 Fees' },
            { key: 'documents', label: '📄 Documents' },
            { key: 'resources', label: '📖 Library' },
            { key: 'support', label: '🎫 Support' },
            { key: 'profile', label: '👤 Profile' },
          ] as { key: Tab; label: string }[]).map(t => (
            <button key={t.key} onClick={() => setActiveTab(t.key)} style={{
              padding: '0.65rem 1rem', border: 'none', background: 'none', cursor: 'pointer',
              fontSize: '0.8rem', fontWeight: 600, whiteSpace: 'nowrap',
              color: activeTab === t.key ? 'var(--primary)' : 'var(--text-muted)',
              borderBottom: activeTab === t.key ? '2px solid var(--primary)' : '2px solid transparent',
              marginBottom: '-2px',
            }}>{t.label}</button>
          ))}
        </div>

        {/* ═══ DASHBOARD TAB ═══ */}
        {activeTab === 'dashboard' && profile && <DashboardTab profile={profile} fees={fees} announcements={announcements} setActiveTab={setActiveTab} />}
        {/* ═══ COURSES TAB ═══ */}
        {activeTab === 'courses' && <CoursesTab authFetch={authFetch} />}
        {/* ═══ TIMETABLE TAB ═══ */}
        {activeTab === 'timetable' && <TimetableTab authFetch={authFetch} />}
        {/* ═══ RESULTS TAB ═══ */}
        {activeTab === 'results' && <ResultsTab authFetch={authFetch} />}
        {/* ═══ EXAMS TAB ═══ */}
        {activeTab === 'exams' && <ExamsTab authFetch={authFetch} />}
        {/* ═══ FEES TAB ═══ */}
        {activeTab === 'fees' && <FeesTab fees={fees} fmt={fmt} />}
        {/* ═══ DOCUMENTS TAB ═══ */}
        {activeTab === 'documents' && <DocumentsTab authFetch={authFetch} />}
        {/* ═══ RESOURCES TAB ═══ */}
        {activeTab === 'resources' && <ResourcesTab authFetch={authFetch} />}
        {/* ═══ SUPPORT TAB ═══ */}
        {activeTab === 'support' && <SupportTab authFetch={authFetch} />}
        {/* ═══ PROFILE TAB ═══ */}
        {activeTab === 'profile' && <ProfileTab profile={profile} authFetch={authFetch} editPhone={editPhone} setEditPhone={setEditPhone} editAddress={editAddress} setEditAddress={setEditAddress} setProfile={setProfile} />}
      </div>
    </div>
  );
};

/* ── Dashboard Tab ── */
const DashboardTab: React.FC<{ profile: any; fees: any; announcements: any[]; setActiveTab: (t: Tab) => void }> = ({ profile, fees, announcements, setActiveTab }) => (
  <div>
    <div className="card" style={{ background: 'linear-gradient(135deg, var(--primary) 0%, var(--primary-mid) 100%)', color: 'white', border: 'none' }}>
      <h2 style={{ fontSize: '1.5rem', fontWeight: 700, marginBottom: '0.5rem', color: 'white' }}>Welcome, {profile.firstName}! 🎓</h2>
      <p style={{ color: 'rgba(255,255,255,0.8)', marginBottom: '1rem' }}>Student ID: <strong>{profile.studentId}</strong></p>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '0.75rem' }}>
        {[{ l: 'Programme', v: profile.programme || 'N/A' }, { l: 'Enrollment', v: profile.enrollmentOption }, { l: 'Type', v: profile.applicationType === 'topup' ? 'Top-Up' : 'Regular' }].map(i => (
          <div key={i.l} style={{ background: 'rgba(255,255,255,0.1)', borderRadius: '8px', padding: '0.875rem' }}>
            <div style={{ fontSize: '0.65rem', textTransform: 'uppercase', letterSpacing: '0.05em', color: 'rgba(255,255,255,0.6)' }}>{i.l}</div>
            <div style={{ fontWeight: 600, fontSize: '0.85rem', marginTop: '0.2rem' }}>{i.v}</div>
          </div>
        ))}
      </div>
    </div>
    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '0.75rem', margin: '1rem 0' }}>
      {[
        { icon: '📚', label: 'Course Registration', tab: 'courses' as Tab },
        { icon: '📅', label: 'My Timetable', tab: 'timetable' as Tab },
        { icon: '📊', label: 'View Results', tab: 'results' as Tab },
        { icon: '📝', label: 'Exam Schedule', tab: 'exams' as Tab },
        { icon: '💰', label: 'Fee Information', tab: 'fees' as Tab },
        { icon: '📄', label: 'Request Document', tab: 'documents' as Tab },
      ].map(a => (
        <div key={a.label} className="card" style={{ margin: 0, cursor: 'pointer', textAlign: 'center', padding: '1.25rem' }} onClick={() => setActiveTab(a.tab)}>
          <div style={{ fontSize: '1.5rem', marginBottom: '0.5rem' }}>{a.icon}</div>
          <div style={{ fontSize: '0.8rem', fontWeight: 600, color: 'var(--primary)' }}>{a.label}</div>
        </div>
      ))}
    </div>
    {fees && (
      <div className="card">
        <h3 className="section-title">Important Dates</h3>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '0.75rem' }}>
          <div style={{ padding: '0.75rem', background: 'var(--success-bg)', borderRadius: '8px', border: '1px solid var(--success-border)' }}>
            <div style={{ fontSize: '0.65rem', fontWeight: 700, color: 'var(--success)', textTransform: 'uppercase' }}>Programme Start</div>
            <div style={{ fontWeight: 600, color: 'var(--primary)', marginTop: '0.2rem' }}>{fees.payment.programmeStartDate}</div>
          </div>
          <div style={{ padding: '0.75rem', background: 'var(--warning-bg)', borderRadius: '8px', border: '1px solid var(--accent)' }}>
            <div style={{ fontSize: '0.65rem', fontWeight: 700, color: 'var(--accent-dark)', textTransform: 'uppercase' }}>Fee Deadline</div>
            <div style={{ fontWeight: 600, color: 'var(--primary)', marginTop: '0.2rem' }}>{fees.payment.initialPaymentDeadline}</div>
          </div>
        </div>
      </div>
    )}
    {announcements.length > 0 && (
      <div className="card" style={{ marginTop: '1rem' }}>
        <h3 className="section-title">📢 Announcements</h3>
        {announcements.map(a => (
          <div key={a.id} style={{ padding: '0.75rem', borderRadius: '6px', marginBottom: '0.5rem', border: `1px solid ${a.priority === 'urgent' ? 'var(--danger)' : a.priority === 'important' ? 'var(--accent)' : 'var(--border)'}`, background: a.priority === 'urgent' ? 'var(--danger-bg)' : a.priority === 'important' ? 'var(--warning-bg)' : 'var(--surface)' }}>
            <strong style={{ fontSize: '0.85rem' }}>{a.title}</strong>
            <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', margin: '0.25rem 0 0' }}>{a.content}</p>
          </div>
        ))}
      </div>
    )}
  </div>
);

/* ── Courses Tab ── */
const CoursesTab: React.FC<{ authFetch: any }> = ({ authFetch }) => {
  const [available, setAvailable] = useState<any[]>([]);
  const [registered, setRegistered] = useState<any[]>([]);
  const [totalCredits, setTotalCredits] = useState(0);
  const [loading, setLoading] = useState(true);
  const [semester, setSemester] = useState(1);
  const [selected, setSelected] = useState<string[]>([]);
  const [registering, setRegistering] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    const [a, r] = await Promise.all([
      authFetch(`${API}/api/students/courses/available?semester=${semester}`),
      authFetch(`${API}/api/students/courses/registered?semester=${semester}`),
    ]);
    if (a?.success) setAvailable(a.courses);
    if (r?.success) { setRegistered(r.registrations); setTotalCredits(r.totalCredits); }
    setLoading(false);
  }, [authFetch, semester]);

  useEffect(() => { load(); }, [load]);

  const handleRegister = async () => {
    if (selected.length === 0) return;
    setRegistering(true);
    const data = await authFetch(`${API}/api/students/courses/register`, { method: 'POST', body: JSON.stringify({ courseIds: selected, semester }) });
    if (data?.success) { setSelected([]); load(); }
    setRegistering(false);
  };

  const handleDrop = async (id: string) => {
    if (!window.confirm('Drop this course?')) return;
    await authFetch(`${API}/api/students/courses/drop/${id}`, { method: 'DELETE' });
    load();
  };

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem', flexWrap: 'wrap', gap: '0.75rem' }}>
        <h2 style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--primary)' }}>Course Registration</h2>
        <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center' }}>
          <select value={semester} onChange={e => setSemester(Number(e.target.value))} style={{ padding: '0.4rem 0.75rem', border: '1.5px solid var(--border)', borderRadius: 'var(--radius-sm)', fontSize: '0.8rem' }}>
            <option value={1}>Semester 1</option><option value={2}>Semester 2</option>
          </select>
          <span className="badge badge-info">Credits: {totalCredits}</span>
        </div>
      </div>

      {registered.length > 0 && (
        <div className="card" style={{ marginBottom: '1rem' }}>
          <h3 className="section-title">My Registered Courses</h3>
          <div className="table-wrap"><table className="data-table"><thead><tr><th>Code</th><th>Title</th><th>Credits</th><th>Lecturer</th><th>Type</th><th></th></tr></thead><tbody>
            {registered.map((r: any) => (
              <tr key={r.id}><td><strong>{r.course_code}</strong></td><td>{r.course_title}</td><td>{r.credit_hours}</td><td>{r.lecturer || '—'}</td>
                <td><span className={`badge ${r.course_type === 'core' ? 'badge-info' : 'badge-neutral'}`}>{r.course_type}</span></td>
                <td><button onClick={() => handleDrop(r.id)} className="btn btn-ghost btn-sm" style={{ color: 'var(--danger)' }}>Drop</button></td></tr>
            ))}
          </tbody></table></div>
        </div>
      )}

      <div className="card">
        <h3 className="section-title">Available Courses</h3>
        {loading ? <p style={{ color: 'var(--text-muted)' }}>Loading...</p> : available.length === 0 ? (
          <p style={{ color: 'var(--text-muted)' }}>No courses available for your programme this semester. Courses will be added by administration.</p>
        ) : (
          <>
            <div className="table-wrap"><table className="data-table"><thead><tr><th></th><th>Code</th><th>Title</th><th>Credits</th><th>Level</th><th>Type</th><th>Lecturer</th></tr></thead><tbody>
              {available.filter(c => !c.is_registered).map((c: any) => (
                <tr key={c.id}>
                  <td><input type="checkbox" checked={selected.includes(c.id)} onChange={e => setSelected(s => e.target.checked ? [...s, c.id] : s.filter(x => x !== c.id))} /></td>
                  <td><strong>{c.course_code}</strong></td><td>{c.course_title}</td><td>{c.credit_hours}</td><td>{c.level}</td>
                  <td><span className={`badge ${c.course_type === 'core' ? 'badge-info' : 'badge-neutral'}`}>{c.course_type}</span></td><td>{c.lecturer || '—'}</td>
                </tr>
              ))}
            </tbody></table></div>
            {selected.length > 0 && (
              <button onClick={handleRegister} disabled={registering} className="btn btn-primary" style={{ marginTop: '1rem' }}>
                {registering ? 'Registering...' : `Register ${selected.length} Course(s)`}
              </button>
            )}
          </>
        )}
      </div>
    </div>
  );
};

/* ── Timetable Tab ── */
const TimetableTab: React.FC<{ authFetch: any }> = ({ authFetch }) => {
  const [timetable, setTimetable] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [semester, setSemester] = useState(1);

  useEffect(() => {
    (async () => { setLoading(true); const d = await authFetch(`${API}/api/students/timetable?semester=${semester}`); if (d?.success) setTimetable(d.timetable); setLoading(false); })();
  }, [authFetch, semester]);

  const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const grouped = days.map(day => ({ day, slots: timetable.filter(t => t.day_of_week === day) }));

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
        <h2 style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--primary)' }}>My Timetable</h2>
        <select value={semester} onChange={e => setSemester(Number(e.target.value))} style={{ padding: '0.4rem 0.75rem', border: '1.5px solid var(--border)', borderRadius: 'var(--radius-sm)', fontSize: '0.8rem' }}>
          <option value={1}>Semester 1</option><option value={2}>Semester 2</option>
        </select>
      </div>
      {loading ? <p>Loading...</p> : timetable.length === 0 ? (
        <div className="card"><p style={{ color: 'var(--text-muted)' }}>No timetable available yet. Check back when administration publishes the schedule.</p></div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
          {grouped.filter(g => g.slots.length > 0).map(g => (
            <div key={g.day} className="card" style={{ margin: 0 }}>
              <h4 style={{ fontSize: '0.9rem', fontWeight: 700, color: 'var(--primary)', marginBottom: '0.75rem' }}>{g.day}</h4>
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                {g.slots.map((s: any) => (
                  <div key={s.id} style={{ display: 'flex', gap: '1rem', alignItems: 'center', padding: '0.5rem 0.75rem', background: 'var(--surface-2)', borderRadius: '6px', border: '1px solid var(--border)' }}>
                    <div style={{ fontWeight: 700, fontSize: '0.8rem', color: 'var(--primary)', minWidth: '100px' }}>{s.start_time?.slice(0, 5)} – {s.end_time?.slice(0, 5)}</div>
                    <div style={{ flex: 1 }}>
                      <div style={{ fontWeight: 600, fontSize: '0.85rem' }}>{s.course_code} — {s.course_title}</div>
                      <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>{s.venue || 'TBD'} · {s.lecturer || ''}</div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

