/* ── Documents Tab ── */
const DocumentsTab: React.FC<{ authFetch: any }> = ({ authFetch }) => {
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [form, setForm] = useState({ documentType: 'transcript', reason: '', copies: 1 });
  const [submitting, setSubmitting] = useState(false);
  const [msg, setMsg] = useState('');

  const load = useCallback(async () => { setLoading(true); const d = await authFetch(`${API}/api/students/document-requests`); if (d?.success) setRequests(d.requests); setLoading(false); }, [authFetch]);
  useEffect(() => { load(); }, [load]);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault(); setSubmitting(true); setMsg('');
    const d = await authFetch(`${API}/api/students/document-requests`, { method: 'POST', body: JSON.stringify(form) });
    if (d?.success) { setMsg('Request submitted!'); setForm({ documentType: 'transcript', reason: '', copies: 1 }); load(); }
    else setMsg(d?.message || 'Failed');
    setSubmitting(false);
  };

  const docTypes: Record<string, string> = { transcript: 'Academic Transcript', recommendation_letter: 'Recommendation Letter', enrollment_letter: 'Enrollment Verification', introduction_letter: 'Introduction Letter', certificate: 'Certificate Copy' };
  const statusBadge = (s: string) => s === 'completed' ? 'badge-success' : s === 'processing' ? 'badge-info' : s === 'rejected' ? 'badge-danger' : 'badge-warning';

  return (
    <div>
      <h2 style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--primary)', marginBottom: '1rem' }}>Document Requests</h2>
      <div className="card">
        <h3 className="section-title">New Request</h3>
        {msg && <div className={`alert ${msg.includes('submitted') ? 'alert-success' : 'alert-error'}`}>{msg}</div>}
        <form onSubmit={submit}>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '1rem' }}>
            <div className="form-group"><label>Document Type</label><select value={form.documentType} onChange={e => setForm(f => ({ ...f, documentType: e.target.value }))}>
              {Object.entries(docTypes).map(([k, v]) => <option key={k} value={k}>{v}</option>)}
            </select></div>
            <div className="form-group"><label>Copies</label><input type="number" min={1} max={5} value={form.copies} onChange={e => setForm(f => ({ ...f, copies: parseInt(e.target.value) || 1 }))} /></div>
          </div>
          <div className="form-group"><label>Reason (optional)</label><input type="text" value={form.reason} onChange={e => setForm(f => ({ ...f, reason: e.target.value }))} placeholder="e.g. For scholarship application" /></div>
          <button type="submit" className="btn btn-primary" disabled={submitting}>{submitting ? 'Submitting...' : 'Submit Request'}</button>
        </form>
      </div>
      {requests.length > 0 && (
        <div className="card" style={{ marginTop: '1rem' }}>
          <h3 className="section-title">My Requests</h3>
          <div className="table-wrap"><table className="data-table"><thead><tr><th>Type</th><th>Copies</th><th>Status</th><th>Date</th><th>Notes</th></tr></thead><tbody>
            {requests.map((r: any) => (
              <tr key={r.id}><td>{docTypes[r.document_type] || r.document_type}</td><td>{r.copies}</td>
                <td><span className={`badge ${statusBadge(r.status)}`}>{r.status}</span></td>
                <td style={{ fontSize: '0.8rem' }}>{new Date(r.created_at).toLocaleDateString()}</td>
                <td style={{ fontSize: '0.8rem' }}>{r.admin_notes || '—'}</td></tr>
            ))}
          </tbody></table></div>
        </div>
      )}
    </div>
  );
};

