/* ── Support Tab ── */
const SupportTab: React.FC<{ authFetch: any }> = ({ authFetch }) => {
  const [tickets, setTickets] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ subject: '', category: 'general', message: '', priority: 'normal' });
  const [submitting, setSubmitting] = useState(false);

  const load = useCallback(async () => { setLoading(true); const d = await authFetch(`${API}/api/students/support-tickets`); if (d?.success) setTickets(d.tickets); setLoading(false); }, [authFetch]);
  useEffect(() => { load(); }, [load]);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault(); setSubmitting(true);
    const d = await authFetch(`${API}/api/students/support-tickets`, { method: 'POST', body: JSON.stringify(form) });
    if (d?.success) { setForm({ subject: '', category: 'general', message: '', priority: 'normal' }); setShowForm(false); load(); }
    setSubmitting(false);
  };

  const statusBadge = (s: string) => s === 'resolved' ? 'badge-success' : s === 'in_progress' ? 'badge-info' : s === 'closed' ? 'badge-neutral' : 'badge-warning';

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
        <h2 style={{ fontSize: '1.25rem', fontWeight: 700, color: 'var(--primary)' }}>Support & Help</h2>
        <button onClick={() => setShowForm(!showForm)} className="btn btn-primary btn-sm">{showForm ? 'Cancel' : '+ New Ticket'}</button>
      </div>
      {showForm && (
        <div className="card" style={{ marginBottom: '1rem' }}>
          <form onSubmit={submit}>
            <div className="form-group"><label>Subject *</label><input type="text" value={form.subject} onChange={e => setForm(f => ({ ...f, subject: e.target.value }))} required /></div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
              <div className="form-group"><label>Category</label><select value={form.category} onChange={e => setForm(f => ({ ...f, category: e.target.value }))}>
                <option value="general">General</option><option value="academic">Academic</option><option value="fees">Fees</option><option value="facilities">Facilities</option><option value="IT">IT / Portal</option>
              </select></div>
              <div className="form-group"><label>Priority</label><select value={form.priority} onChange={e => setForm(f => ({ ...f, priority: e.target.value }))}>
                <option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option>
              </select></div>
            </div>
            <div className="form-group"><label>Message *</label><textarea value={form.message} onChange={e => setForm(f => ({ ...f, message: e.target.value }))} required rows={4} style={{ width: '100%', padding: '0.5rem', border: '1.5px solid var(--border)', borderRadius: 'var(--radius-sm)', fontSize: '0.875rem', resize: 'vertical' }} /></div>
            <button type="submit" className="btn btn-primary" disabled={submitting}>{submitting ? 'Submitting...' : 'Submit Ticket'}</button>
          </form>
        </div>
      )}
      {loading ? <p>Loading...</p> : tickets.length === 0 ? (
        <div className="card"><p style={{ color: 'var(--text-muted)' }}>No support tickets yet. Click "New Ticket" if you need help.</p></div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
          {tickets.map((t: any) => (
            <div key={t.id} className="card" style={{ margin: 0 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '0.5rem' }}>
                <strong style={{ fontSize: '0.9rem' }}>{t.subject}</strong>
                <span className={`badge ${statusBadge(t.status)}`}>{t.status}</span>
              </div>
              <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', margin: 0 }}>{t.message}</p>
              {t.admin_reply && (
                <div style={{ marginTop: '0.75rem', padding: '0.75rem', background: 'var(--success-bg)', borderRadius: '6px', border: '1px solid var(--success-border)' }}>
                  <div style={{ fontSize: '0.7rem', fontWeight: 700, color: 'var(--success)', marginBottom: '0.25rem' }}>Admin Reply</div>
                  <p style={{ fontSize: '0.85rem', margin: 0 }}>{t.admin_reply}</p>
                </div>
              )}
              <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: '0.5rem' }}>
                {new Date(t.created_at).toLocaleDateString()} · {t.category}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

/* ── Profile Tab ── */
const ProfileTab: React.FC<{ profile: any; authFetch: any; editPhone: string; setEditPhone: (v: string) => void; editAddress: string; setEditAddress: (v: string) => void; setProfile: (p: any) => void }> = ({ profile, authFetch, editPhone, setEditPhone, editAddress, setEditAddress, setProfile }) => {
  const [msg, setMsg] = useState('');
  const [saving, setSaving] = useState(false);
  const [pwForm, setPwForm] = useState({ currentPassword: '', newPassword: '', confirm: '' });
  const [pwMsg, setPwMsg] = useState('');
  const [pwSaving, setPwSaving] = useState(false);

  const saveProfile = async (e: React.FormEvent) => {
    e.preventDefault(); setSaving(true); setMsg('');
    const d = await authFetch(`${API}/api/students/profile`, { method: 'PUT', body: JSON.stringify({ phone: editPhone, postalAddress: editAddress }) });
    if (d?.success) { setMsg('Profile updated!'); setProfile((p: any) => p ? { ...p, phone: editPhone, postalAddress: editAddress } : null); }
    else setMsg(d?.message || 'Failed');
    setSaving(false);
  };

  const changePw = async (e: React.FormEvent) => {
    e.preventDefault();
    if (pwForm.newPassword !== pwForm.confirm) { setPwMsg('Passwords do not match'); return; }
    setPwSaving(true); setPwMsg('');
    const d = await authFetch(`${API}/api/students/change-password`, { method: 'POST', body: JSON.stringify({ currentPassword: pwForm.currentPassword, newPassword: pwForm.newPassword }) });
    if (d?.success) { setPwMsg('Password changed!'); setPwForm({ currentPassword: '', newPassword: '', confirm: '' }); }
    else setPwMsg(d?.message || 'Failed');
    setPwSaving(false);
  };

  return (
    <div>
      <div className="card">
        <h3 className="section-title">Personal Information</h3>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '0.75rem' }}>
          {[{ l: 'Student ID', v: profile.studentId }, { l: 'Name', v: `${profile.firstName} ${profile.otherNames || ''} ${profile.lastName}`.trim() }, { l: 'Email', v: profile.email }, { l: 'Phone', v: profile.phone }, { l: 'Date of Birth', v: profile.dateOfBirth ? new Date(profile.dateOfBirth).toLocaleDateString() : '—' }, { l: 'Gender', v: profile.gender }, { l: 'Hometown', v: profile.hometown }, { l: 'Programme', v: profile.programme }].map(i => (
            <div key={i.l} className="detail-row"><span className="detail-label">{i.l}</span><span className="detail-value">{i.v}</span></div>
          ))}
        </div>
      </div>
      <div className="card" style={{ marginTop: '1rem' }}>
        <h3 className="section-title">Update Contact</h3>
        {msg && <div className={`alert ${msg.includes('updated') ? 'alert-success' : 'alert-error'}`}>{msg}</div>}
        <form onSubmit={saveProfile}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
            <div className="form-group"><label>Phone</label><input type="text" value={editPhone} onChange={e => setEditPhone(e.target.value)} /></div>
            <div className="form-group"><label>Postal Address</label><input type="text" value={editAddress} onChange={e => setEditAddress(e.target.value)} /></div>
          </div>
          <button type="submit" className="btn btn-primary" disabled={saving}>{saving ? 'Saving...' : 'Update'}</button>
        </form>
      </div>
      <div className="card" style={{ marginTop: '1rem' }}>
        <h3 className="section-title">Change Password</h3>
        {pwMsg && <div className={`alert ${pwMsg.includes('changed') ? 'alert-success' : 'alert-error'}`}>{pwMsg}</div>}
        <form onSubmit={changePw}>
          <div className="form-group"><label>Current Password</label><input type="password" value={pwForm.currentPassword} onChange={e => setPwForm(f => ({ ...f, currentPassword: e.target.value }))} required /></div>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
            <div className="form-group"><label>New Password</label><input type="password" value={pwForm.newPassword} onChange={e => setPwForm(f => ({ ...f, newPassword: e.target.value }))} required minLength={8} /></div>
            <div className="form-group"><label>Confirm</label><input type="password" value={pwForm.confirm} onChange={e => setPwForm(f => ({ ...f, confirm: e.target.value }))} required /></div>
          </div>
          <button type="submit" className="btn btn-primary" disabled={pwSaving}>{pwSaving ? 'Changing...' : 'Change Password'}</button>
        </form>
      </div>
    </div>
  );
};

export default StudentDashboard;
